code.text:
packer {
  required_plugins {
    amazon = { source = "github.com/hashicorp/amazon", version = "~> 1.3" }
  }
}
variable "version" { type = string }
source "amazon-ebs" "al2023" {
  region        = "us-east-1"
  instance_type = "t3.small"
  ssh_username  = "ec2-user"
  ami_name      = "golden-al2023-${var.version}"
  source_ami_filter {
    filters     = { name = "al2023-ami-*-x86_64" }
    owners      = ["amazon"]
    most_recent = true
  }
}
build {
  sources = ["source.amazon-ebs.al2023"]
  provisioner "shell" { inline = ["sudo dnf -y update", "sudo dnf -y install nginx"] }
}

build {
  sources = ["source.amazon-ebs.al2023"]
  provisioner "ansible" {
    playbook_file = "hardening/cis-level1.yml"
  }
  provisioner "inspec" {
    profile = "https://github.com/dev-sec/linux-baseline"
  }
}

data "aws_ssm_parameter" "golden" {
  name = "/images/golden-al2023/prod"   # updated by promotion pipeline
}
resource "aws_launch_template" "app" {
  image_id = data.aws_ssm_parameter.golden.value
}
